build(dict(S,ch="living-creatures-exploring-their-characteristics",topic="food-habits-of-animals",name_en="What animals eat",name_ta="விலங்குகள் உண்ணும் உணவு",
 objectives=["Name herbivores, carnivores and omnivores","Match animals with their food"],
 story=("At the zoo","At the zoo Teja watched a deer nibbling grass and a lion resting near some meat. A crow nearby pecked at both fruit and a small insect.\n\"Why do they eat different things?\" he asked the guide."),
 explain=["Animals that eat only plants are called herbivores, such as cows, deer and elephants. Animals that eat only other animals are called carnivores, such as lions, tigers and eagles.","Animals that eat both plants and animals are called omnivores, such as crows, bears and humans.","Their bodies suit their food. Herbivores have flat teeth to grind plants. Carnivores have sharp pointed teeth to tear meat."],
 terms=["herbivore","carnivore","omnivore","teeth"],
 narr=[("Animals that eat only plants are herbivores, like cows and deer.","herbivores"),("Animals that eat only other animals are carnivores, like lions.","carnivores"),("Animals that eat both are omnivores, like crows and humans.","omnivores"),("Herbivores have flat teeth. Carnivores have sharp teeth.","teeth suit food")],
 ex=("A bear eats fruit, honey and fish. What kind of eater is it?",[("It eats plant foods like fruit and honey.","Plants."),("It also eats fish, an animal.","Animals."),("So a bear is an omnivore.","It eats both.")]),
 tb=("A friend says all animals with sharp teeth only eat meat. How will you explain?",["Some animals such as bears have sharp teeth but also eat plants.","They are omnivores."],["Judging food by teeth alone."]),
 summary=["Herbivores eat plants, carnivores eat animals, omnivores eat both.","Teeth suit the food.","Humans are omnivores."],
 q=[("mcq",1,"r1-herb","A cow is a","herbivore",[("carnivore","Cows eat plants."),("omnivore","Cows eat only plants.")],"It eats only plants."),
    ("tf",1,"r1-lion","A lion is a carnivore.",True,"True."),
    ("mcq",2,"r2-omni","An animal that eats both plants and animals is","omnivore",[("herbivore","Herbivores eat plants only."),("carnivore","Carnivores eat animals only.")],"Crows and humans are omnivores."),
    ("tf",2,"r2-teeth","Carnivores have sharp pointed teeth.",True,"True."),
    ("mcq",3,"r3-flat","Flat teeth are best for","grinding plants",[("tearing meat","Pointed teeth do that."),("flying","Teeth are not for flying.")],"Herbivores grind leaves."),
    ("short",3,"r3-name","Name one herbivore.",["cow","deer","elephant","goat","sheep","buffalo","horse","rabbit","giraffe"],"Cows and deer eat only plants."),
    ("mcq",4,"r4-human","Humans are","omnivores",[("herbivores","Many people eat meat too."),("carnivores","We eat plants as well.")],"We eat plants and animals."),
    ("tf",4,"r4-tiger","A tiger eats only plants.",False,"False.")]))
build(dict(S,ch="temperature-and-its-measurement",topic="using-a-thermometer",name_en="Using a thermometer",name_ta="வெப்பமானியைப் பயன்படுத்துதல்",
 objectives=["Read a clinical and a laboratory thermometer","Say normal body temperature"],
 story=("Fever at home","Arun felt hot and tired. His mother put a thermometer under his tongue for a minute.\nThe silver line stopped at 38.5 degrees. \"You have a fever,\" she said. \"Normal is about 37.\""),
 explain=["A thermometer measures temperature in degrees Celsius, written °C. A clinical thermometer measures body temperature and has a range from 35 °C to 42 °C. Normal human body temperature is about 37 °C.","Before use, shake it so the liquid falls below 35 °C. Place it under the tongue or arm, wait about a minute, and read where the liquid stops, keeping your eye level with it.","A laboratory thermometer has a larger range, such as −10 °C to 110 °C, and is used to measure the temperature of water and other things, never of the body. Do not touch the bulb when reading and handle it gently because glass can break."],
 terms=["thermometer","Celsius","clinical thermometer","range"],
 narr=[("A thermometer measures temperature in degrees Celsius.","degrees Celsius"),("Normal body temperature is about 37 degrees. A higher reading means fever.","37 and fever"),("Shake the clinical thermometer first, wait one minute, and read at eye level.","how to use"),("A laboratory thermometer measures things like water. It is not for the body.","laboratory thermometer")],
 ex=("The clinical thermometer reads 39 °C. What does it tell us?",[("Normal body temperature is about 37 °C.","This is the reference."),("39 °C is higher than 37 °C.","It is 2 degrees higher."),("So the person has a fever and should see a doctor.","A fever may mean illness.")]),
 tb=("A friend wants to use a laboratory thermometer to measure body temperature. What will you say?",["Its range is large and it is not made for the body.","A clinical thermometer is the correct one."],["Using any thermometer for any purpose."]),
 summary=["Temperature is measured in °C with a thermometer.","Normal body temperature is about 37 °C.","Shake before use, wait a minute, read at eye level."],
 q=[("mcq",1,"r1-unit","Temperature is measured in","degrees Celsius",[("kilograms","That is mass."),("litres","That is volume.")],"The symbol is °C."),
    ("tf",1,"r1-norm","Normal body temperature is about 37 °C.",True,"True."),
    ("mcq",2,"r2-clin","The instrument for measuring body temperature is the","clinical thermometer",[("laboratory thermometer","That is for water and other things."),("ruler","A ruler measures length.")],"It has a range of 35 to 42 °C."),
    ("tf",2,"r2-shake","We should shake a clinical thermometer before use.",True,"True."),
    ("mcq",3,"r3-fever","A reading of 39 °C means","fever",[("normal","Normal is about 37."),("very cold","It is above normal.")],"It is higher than normal."),
    ("short",3,"r3-sym","Write the symbol for degrees Celsius.",["°c","c","degree celsius","degrees celsius"],"The symbol is °C."),
    ("mcq",4,"r4-eye","While reading a thermometer, keep your eye","level with the liquid",[("far away","Read from close, level."),("below it","Keep it level.")],"This avoids reading errors."),
    ("tf",4,"r4-bulb","A thermometer is made of glass and must be handled with care.",True,"True.")]))
build(dict(S,ch="natures-treasures",topic="forests-and-biodiversity",name_en="Forests and their importance",name_ta="காடுகளின் முக்கியத்துவம்",
 objectives=["Say how forests help us","Say how we can protect forests"],
 story=("The tree cutters","When the trees on the hill were cut, the stream near Mani's village dried up and the monsoon floods washed away the soil.\nHis teacher said, \"Forests are like sponges. They hold water and soil.\"\nThe village decided to plant new trees."),
 explain=["Forests are large areas full of trees, plants and animals. They give us wood, fruits, medicines, honey and many other things.","Trees give out oxygen, take in carbon dioxide, hold the soil with their roots, bring rain and give shade. Forests are homes to many animals and birds.","We protect forests by not cutting trees without need, planting new trees, preventing forest fires and protecting wild animals. Many communities, such as the Bishnois of Rajasthan, have protected trees for centuries."],
 terms=["forest","oxygen","wildlife","deforestation"],
 narr=[("Forests give us wood, fruit, honey and medicines.","forest products"),("Trees give oxygen, hold the soil and bring rain.","trees help the earth"),("Forests are homes of many animals and birds.","wildlife"),("We protect forests by planting trees and not cutting them without need.","protect forests")],
 ex=("What can happen if too many trees on a hill are cut?",[("Roots no longer hold the soil.","Soil becomes loose."),("Heavy rain washes the soil away and causes floods.","This is soil erosion."),("Animals also lose their homes. So we must protect forests.","Everything is connected.")]),
 tb=("A friend says cutting one tree does not matter. How will you reply?",["If everyone cuts a tree, a forest disappears.","We should plant a tree for every one we cut."],["Thinking small actions never add up."]),
 summary=["Forests give us many useful things.","Trees give oxygen and hold soil.","We must protect forests."],
 q=[("mcq",1,"r1-oxy","Trees give out","oxygen",[("smoke","Trees give oxygen."),("plastic","Trees do not give plastic.")],"We breathe oxygen."),
    ("tf",1,"r1-home","Forests are homes of many animals.",True,"True."),
    ("mcq",2,"r2-soil","Roots of trees","hold the soil",[("break the soil","Roots hold it."),("dry the soil","They hold soil.")],"This reduces erosion."),
    ("tf",2,"r2-cut","Cutting trees without need is good for nature.",False,"False."),
    ("mcq",3,"r3-prot","Which action protects forests?","planting trees",[("lighting fires","Fires destroy forests."),("hunting wild animals","That harms wildlife.")],"Trees renew forests."),
    ("short",3,"r3-prod","Name one thing we get from a forest.",["wood","fruit","honey","medicine","medicines","timber","fruits","gum","bamboo"],"Forests give wood, honey and more."),
    ("mcq",4,"r4-defor","Cutting down forests on a large scale is called","deforestation",[("afforestation","That is planting forests."),("conservation","That is protecting."),],"Deforestation harms the environment."),
    ("tf",4,"r4-bish","Some communities have protected trees for centuries.",True,"True.")]))
build(dict(S,ch="exploring-magnets",topic="making-a-magnet-and-a-compass",name_en="Making a magnet and a compass",name_ta="காந்தமும் திசைகாட்டியும் செய்தல்",
 objectives=["Make a magnet by stroking an iron needle","Make a simple compass"],
 story=("The floating needle","Kiran stroked a steel needle with a bar magnet fifty times in one direction. Then he laid the needle on a leaf floating in a bowl of water.\nThe needle slowly turned until it pointed north and south.\n\"My needle became a compass!\" he cheered."),
 explain=["An iron or steel needle can be made into a magnet by stroking it many times in one direction with one pole of a bar magnet. It should be lifted away after each stroke.","A freely hanging or floating magnet always settles in the north-south direction. A needle magnetised this way and floated on a leaf in water makes a simple compass.","A real compass has a magnetised needle on a pivot. It is used by sailors, hikers and pilots to find directions. Keep magnets away from mobile phones and cards and do not drop or heat them because they can lose their magnetism."],
 terms=["magnetise","pivot","compass","direction"],
 narr=[("A steel needle becomes a magnet when stroked many times in one direction with a bar magnet.","stroking"),("A magnetised needle floating on a leaf turns north-south. This is a simple compass.","simple compass"),("A real compass has a needle that spins on a pivot. Sailors and hikers use it.","real compass"),("Do not drop or heat magnets. They can lose their magnetism.","care of magnets")],
 ex=("Why must we stroke the needle only in one direction?",[("Stroking in one direction lines up the tiny magnetic parts inside the needle.","They point the same way."),("Back and forth strokes would undo the lining up.","They would mix the directions."),("So one-direction strokes make a stronger magnet.","The needle becomes magnetised.")]),
 tb=("A friend says a magnet can be made by only touching a needle once. What will you say?",["A needle must be stroked many times in the same direction.","One touch gives only a very weak magnet."],["Thinking one touch is enough."]),
 summary=["Stroking a needle with a magnet in one direction makes a magnet.","A floating magnet makes a simple compass.","A compass shows north and south."],
 q=[("mcq",1,"r1-stroke","To magnetise a needle, stroke it with a magnet","in one direction many times",[("once only","One stroke is too weak."),("back and forth","That mixes the directions.")],"Repeated one-way strokes work."),
    ("tf",1,"r1-leaf","A magnetised needle floating on a leaf points north-south.",True,"True."),
    ("mcq",2,"r2-comp","A compass is used to find","directions",[("weight","A balance finds weight."),("time","A clock tells time.")],"Its needle points north-south."),
    ("tf",2,"r2-heat","Heating a magnet makes it stronger.",False,"False. It can weaken it."),
    ("mcq",3,"r3-care","Magnets should be kept away from","mobile phones and cards",[("books","Books are not affected."),("pencils","Pencils are not affected.")],"They can be damaged."),
    ("short",3,"r3-user","Name one person who uses a compass.",["sailor","hiker","pilot","traveller","captain","scout","trekker","mountaineer"],"Sailors and hikers use compasses."),
    ("mcq",4,"r4-pivot","The needle of a real compass turns on a","pivot",[("hammer","A hammer is a tool."),("wheel","A wheel does not hold a needle.")],"A pivot lets it spin freely."),
    ("tf",4,"r4-iron","Only iron or steel can be magnetised easily.",True,"True.")]))
